const common = (request_id, now) => ({
  mode:'READ_ONLY', instrument:'EUR/USD', quote_kind:'reference_rate', source:'ecb-exr-eurusd-reference',
  source_url:'https://www.ecb.europa.eu/stats/eurofxref/eurofxref-daily.xml',
  unit:'USD per EUR', timezone:'Europe/Berlin', retrieved_at:now.toISOString(),
  ...(request_id ? {request_id} : {}),
});
const items=$input.all();
const payload=items.length===1 ? items[0].json : null;
const safeId = value => typeof value==='string' && /^[A-Za-z0-9_-]{1,128}$/.test(value);
const request_id = safeId(payload?.request_id) ? payload.request_id : null;
const valid=payload && typeof payload==='object' && !Array.isArray(payload) &&
  Object.keys(payload).every(key=>['instrument','request_id'].includes(key)) &&
  (!Object.hasOwn(payload,'request_id') || request_id) &&
  (!Object.hasOwn(payload,'instrument') || payload.instrument==='EUR/USD');
if (!valid) return [{json:{...common(request_id,new Date()),status:'unavailable',error:{code:'UNSUPPORTED_QUOTE_REQUEST'}}}];
return [{json:{request_id,decision:'fetch'}}];

const items=$input.all();
const data=items.length===1?items[0].json.data:null;
if (typeof data !== 'string' || !data.trim() || data.length>32768 || /<!DOCTYPE|<!ENTITY/i.test(data)) {
  return [{json:{decision:'invalid_feed'}}];
}
return [{json:{decision:'parse',data}}];

const common = (request_id, now) => ({
  mode:'READ_ONLY', instrument:'EUR/USD', quote_kind:'reference_rate', source:'ecb-exr-eurusd-reference',
  source_url:'https://www.ecb.europa.eu/stats/eurofxref/eurofxref-daily.xml',
  unit:'USD per EUR', timezone:'Europe/Berlin', retrieved_at:now.toISOString(),
  ...(request_id ? {request_id} : {}),
});

function workingDay(day) {
  const month=day.getUTCMonth()+1, date=day.getUTCDate(), year=day.getUTCFullYear();
  if ([0,6].includes(day.getUTCDay()) || (month===1 && date===1) || (month===5 && date===1) ||
      (month===12 && [25,26].includes(date))) return false;
  const a=year%19, b=Math.floor(year/100), c=year%100, d=Math.floor(b/4), e=b%4;
  const f=Math.floor((b+8)/25), g=Math.floor((b-f+1)/3);
  const h=(19*a+b-d-g+15)%30, i=Math.floor(c/4), k=c%4;
  const l=(32+2*e+2*i-h-k)%7, m=Math.floor((a+11*h+22*l)/451);
  const offsets=h+l-7*m+114;
  const easter=Date.UTC(year,Math.floor(offsets/31)-1,offsets%31+1);
  return day.valueOf()!==easter-2*86400000 && day.valueOf()!==easter+86400000;
}
const local = new Intl.DateTimeFormat('en-GB', {
  timeZone:'Europe/Berlin',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',hourCycle:'h23'
});
const getCivilDate = now => {
  const fields=Object.fromEntries(local.formatToParts(now).map(part=>[part.type,part.value]));
  return {date:fields.year+'-'+fields.month+'-'+fields.day,hour:Number(fields.hour)};
};
function expectedDate(now) {
  const localDay=getCivilDate(now);
  const day=new Date(localDay.date+'T00:00:00.000Z');
  if (localDay.hour<17) day.setUTCDate(day.getUTCDate()-1);
  while (!workingDay(day)) day.setUTCDate(day.getUTCDate()-1);
  return {today:localDay.date,expected:day.toISOString().slice(0,10)};
}

const internal=$('Провери заявката за курс').first().json;
const now=new Date();
const base=common(internal.request_id,now);
const calendar=expectedDate(now);
const freshness = {expected_observation_date:calendar.expected,cutoff_local:'17:00',reference_calendar:'TARGET'};
const unavailable = code => [{json:{...base,status:'unavailable',freshness:{...freshness,state:'unavailable'},error:{code}}}];
const items=$input.all();
if (items.length!==1 || items[0].json?.error) return unavailable('ECB_UNAVAILABLE');
const envelope=items[0].json?.['gesmes:Envelope'];
if (envelope?.$?.xmlns!=='http://www.ecb.int/vocabulary/2002-08-01/eurofxref' ||
    envelope['gesmes:subject']!=='Reference rates' ||
    envelope['gesmes:Sender']?.['gesmes:name']!=='European Central Bank') return unavailable('ECB_INVALID_FEED');
const dataset=envelope.Cube?.Cube;
const value=dataset?.$?.time;
const entries=dataset?.Cube;
if (typeof value!=='string' || !/^\d{4}-\d{2}-\d{2}$/.test(value) || !Array.isArray(entries)) {
  return unavailable('ECB_INVALID_OBSERVATION');
}
const observed=new Date(value+'T00:00:00.000Z');
if (!Number.isFinite(observed.valueOf()) || observed.toISOString().slice(0,10)!==value ||
    value>calendar.today || !workingDay(observed)) return unavailable('ECB_INVALID_OBSERVATION');
const usd=entries.filter(entry=>entry?.$?.currency==='USD');
const rate=usd[0]?.$?.rate;
if (usd.length!==1 || typeof rate!=='string' ||
    !/^(?:0|[1-9]\d{0,8})(?:\.\d{1,12})?$/.test(rate) || Number(rate)<=0) {
  return unavailable('ECB_INVALID_USD_RATE');
}
if (value<calendar.expected) {
  return [{json:{...base,status:'stale',observation_date:value,freshness:{...freshness,state:'stale'},
    error:{code:'ECB_STALE_OBSERVATION'}}}];
}
return [{json:{...base,status:'ok',rate,observation_date:value,freshness:{...freshness,state:'as_published'}}}];

const common = (request_id, now) => ({
  mode:'READ_ONLY', instrument:'EUR/USD', quote_kind:'reference_rate', source:'ecb-exr-eurusd-reference',
  source_url:'https://www.ecb.europa.eu/stats/eurofxref/eurofxref-daily.xml',
  unit:'USD per EUR', timezone:'Europe/Berlin', retrieved_at:now.toISOString(),
  ...(request_id ? {request_id} : {}),
});
const request=$('Провери заявката за курс').first().json;
const reason=$input.all()[0]?.json?.decision==='invalid_feed'?'ECB_INVALID_FEED':'ECB_UNAVAILABLE';
return [{json:{...common(request.request_id,new Date()),status:'unavailable',freshness:{state:'unavailable',cutoff_local:'17:00',reference_calendar:'TARGET'},error:{code:reason}}}];
